css:
:root {
  --n: #0D2B4E;
  --n2: #16396b;
  --g: #B8860B;
  --g2: #9a7009;
  --gr: #1E7A34;
  --r: #C00000;
  --r2: #8B0000;
  --or: #C96A00;
  --teal: #0E7C86;
  --gy: #595959;
  --lg: #8C8C8C;
  --bg: #EEF1F7;
  --card: #ffffff;
  --border: #D8DEF0;
  --text: #1a1a2e;
  --shadow: 0 2px 14px rgba(13, 43, 78, 0.10);
}

/* hide ERPNext website header/footer */
.navbar,
.web-footer,
.page-header,
.breadcrumb-container,
footer,
.footer-powered,
.page-breadcrumbs,
.website-footer {
  display: none !important;
}

.web-page-content,
.page_content,
.main-section,
.container,
.container-fluid,
.page-container {
  max-width: 100% !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
}

* {
  box-sizing: border-box;
}

html,
body {
  background: var(--bg) !important;
  font-family: "Segoe UI", Arial, sans-serif !important;
  color: var(--text);
  font-size: 13px;
}

.life-page {
  width: 100%;
  min-height: 100vh;
  background: var(--bg);
  padding-bottom: 40px;
}

/* header */

.life-hdr {
  background: linear-gradient(90deg, #071d35 0%, var(--n) 60%, #0a2240 100%);
  color: #ffffff;
  min-height: 60px;
  display: flex;
  align-items: center;
  padding: 0 22px;
  gap: 14px;
  position: sticky;
  top: 0;
  z-index: 300;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.30);
}

.life-logo {
  width: 40px;
  height: 40px;
  background: var(--g);
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 900;
  color: #ffffff;
  flex-shrink: 0;
}

.life-title {
  font-size: 15px;
  font-weight: 800;
  line-height: 1.2;
}

.life-sub {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.65);
}

.life-module {
  background: rgba(184, 134, 11, 0.25);
  border: 1px solid var(--g);
  padding: 5px 12px;
  border-radius: 16px;
  font-size: 11.5px;
  font-weight: 800;
  color: #f5d675;
  letter-spacing: 0.3px;
}

.life-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}



.hbtn {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #ffffff;
  padding: 6px 12px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 11.5px;
  font-family: inherit;
}

.hbtn:hover {
  background: rgba(255, 255, 255, 0.22);
}

.hbtn.gold {
  background: var(--g);
  border-color: var(--g);
}

/* wizard */

.wizard {
  background: #ffffff;
  border-bottom: 2px solid var(--border);
  padding: 14px 22px;
  display: flex;
  align-items: center;
  overflow-x: auto;
  position: sticky;
  top: 60px;
  z-index: 200;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

.wz-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 105px;
  position: relative;
  flex: 1;
  cursor: pointer;
}

.wz-step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 16px;
  left: calc(50% + 18px);
  right: calc(-50% + 18px);
  height: 2px;
  background: #e0e0e0;
  z-index: 0;
}

.wz-step.done:not(:last-child)::after,
.wz-step.active:not(:last-child)::after {
  background: var(--g);
}

.wz-dot {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2.5px solid #dddddd;
  background: #ffffff;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
  color: #aaaaaa;
}

.wz-step.done .wz-dot {
  background: var(--gr);
  border-color: var(--gr);
  color: #ffffff;
}

.wz-step.active .wz-dot {
  background: var(--n);
  border-color: var(--n);
  color: #ffffff;
  box-shadow: 0 0 0 5px rgba(13, 43, 78, 0.12);
}

.wz-label {
  font-size: 9.5px;
  color: var(--lg);
  margin-top: 5px;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
}

.wz-step.done .wz-label {
  color: var(--gr);
}

.wz-step.active .wz-label {
  color: var(--n);
  font-weight: 900;
}

/* layout */

.main {
  max-width: 1300px;
  margin: 0 auto;
  padding: 20px 18px;
}

.page {
  display: none;
}

.page.active {
  display: block;
}

/* cards */

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  margin-bottom: 18px;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.card-hdr {
  background: var(--n);
  color: #ffffff;
  padding: 12px 18px;
  font-size: 13.5px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.card-body {
  padding: 18px;
}

.card-sub-hdr {
  background: linear-gradient(90deg, #E7ECF2, #ffffff);
  border-bottom: 2px solid var(--g);
  padding: 9px 18px;
  font-size: 12px;
  font-weight: 800;
  color: var(--n);
  margin: 18px -18px 12px;
}

/* form */

.fg {
  display: grid;
  gap: 12px;
}

.fg-2 {
  grid-template-columns: 1fr 1fr;
}

.fg-3 {
  grid-template-columns: 1fr 1fr 1fr;
}

.fg-4 {
  grid-template-columns: 1fr 1fr 1fr 1fr;
}

.f {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.lbl {
  font-size: 10px;
  font-weight: 800;
  color: var(--n);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.req {
  color: var(--r);
}

.inp,
.sel {
  width: 100%;
  padding: 8px 11px;
  border: 1.5px solid #cdd5e0;
  border-radius: 7px;
  font-size: 13px;
  font-family: inherit;
  color: var(--text);
  background: #ffffff;
  height: 38px;
}

.inp:focus,
.sel:focus,
.ta:focus {
  border-color: var(--n);
  outline: none;
  box-shadow: 0 0 0 3px rgba(13, 43, 78, 0.07);
}

.inp:disabled,
.sel:disabled {
  background: #ffffff !important;
  color: var(--text) !important;
  border-color: #cdd5e0 !important;
  opacity: 1 !important;
  -webkit-text-fill-color: var(--text) !important;
}

.ta {
  width: 100%;
  padding: 8px 11px;
  border: 1.5px solid #cdd5e0;
  border-radius: 7px;
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
  min-height: 80px;
  line-height: 1.6;
}

/* buttons */

.btn {
  padding: 9px 18px;
  border-radius: 7px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  border: none;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: 0.12s;
}

.btn-n {
  background: var(--n);
  color: #ffffff;
}

.btn-n:hover {
  background: var(--n2);
}

.btn-g {
  background: var(--g);
  color: #ffffff;
}

.btn-g:hover {
  background: var(--g2);
}

.btn-gr {
  background: var(--gr);
  color: #ffffff;
}

.btn-r {
  background: var(--r);
  color: #ffffff;
}

.btn-or {
  background: var(--or);
  color: #ffffff;
}

.btn-gy {
  background: #f0f0f0;
  color: var(--gy);
  border: 1px solid #dddddd;
}

.btn-row {
  display: flex !important;
  width: 100% !important;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 16px;
  align-items: center !important;
  justify-content: space-between !important;
}

.btn-row .btn-gy {
  margin-right: auto !important;
}

.btn-row .btn-n,
.btn-row .btn-gr {
  margin-left: auto !important;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* pills */

.pill {
  display: inline-block;
  padding: 3px 9px;
  border-radius: 10px;
  font-size: 10.5px;
  font-weight: 800;
  white-space: nowrap;
}

.p-blue {
  background: #E7ECF2;
  color: var(--n);
}

.p-green {
  background: #E8F5E9;
  color: #1B5E20;
}

.p-red {
  background: #FFEBEE;
  color: #B71C1C;
}

.p-gold {
  background: #FFFDE7;
  color: #827717;
}

.p-teal {
  background: #E0F7FA;
  color: #006064;
}

.p-gy {
  background: #F5F5F5;
  color: #424242;
}

.p-or {
  background: #FFF3E0;
  color: #E65100;
}

/* alerts */

.alert {
  border-radius: 9px;
  padding: 14px 16px;
  margin-bottom: 14px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.alert .ai {
  font-size: 22px;
  flex-shrink: 0;
}

.alert .ah {
  font-size: 13px;
  font-weight: 800;
  margin-bottom: 4px;
}

.alert .ab {
  font-size: 12.5px;
  line-height: 1.7;
}

.alert-red {
  background: #FFEBEE;
  border: 2px solid var(--r);
}

.alert-red .ah {
  color: var(--r2);
}

.alert-gold {
  background: #FFFDE7;
  border: 2px solid var(--g);
}

.alert-gold .ah {
  color: #5a4000;
}

.alert-gr {
  background: #E8F5E9;
  border: 2px solid var(--gr);
}

.alert-gr .ah {
  color: #1B5E20;
}

.alert-or {
  background: #FFF3E0;
  border: 2px solid var(--or);
}

.alert-or .ah {
  color: #7f3300;
}

/* search */

.search-big {
  display: flex;
  gap: 10px;
  align-items: center;
}

.search-big input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--border);
  border-radius: 10px;
  font-size: 14px;
  font-family: inherit;
}

.search-big input:focus {
  border-color: var(--n);
  outline: none;
  box-shadow: 0 0 0 3px rgba(13, 43, 78, 0.08);
}

.client-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1.5px solid var(--border);
  border-radius: 10px;
  margin-bottom: 8px;
  background: #ffffff;
  cursor: pointer;
  transition: 0.13s;
}

.client-row:hover {
  border-color: var(--n);
  box-shadow: 0 3px 14px rgba(13, 43, 78, 0.12);
}

.avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--n), var(--teal));
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 900;
  flex-shrink: 0;
}

.client-main {
  flex: 1;
}

.client-name {
  font-size: 14.5px;
  font-weight: 800;
  color: var(--n);
}

.client-meta {
  font-size: 12px;
  color: var(--gy);
  margin-top: 2px;
}

.client-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 6px;
}

/* client profile */

.profile-top {
  display: flex;
  gap: 16px;
  align-items: center;
  background: linear-gradient(135deg, #E7ECF2, #ffffff);
  padding: 18px;
  border-bottom: 2px solid var(--border);
}

.b2b-profile-top-with-photo {
  justify-content: space-between;
  align-items: flex-start;
}

.b2b-profile-left {
  display: flex;
  gap: 16px;
  align-items: center;
  min-width: 0;
}

.b2b-client-photo-box {
  width: 135px;
  flex-shrink: 0;
  text-align: center;
  margin-left: auto;
}

.b2b-client-photo-title {
  font-size: 10px;
  font-weight: 900;
  color: var(--n);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.b2b-client-photo-frame {
  width: 120px;
  height: 120px;
  border: 2px dashed var(--border);
  border-radius: 12px;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  margin-left: auto;
  margin-right: auto;
  position: relative;
}

.b2b-client-photo-frame.has-photo {
  border-style: solid;
  border-color: var(--n);
}

.b2b-client-photo-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.b2b-client-photo-frame input[type="file"] {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.b2b-client-photo-empty {
  color: var(--lg);
  font-size: 24px;
  line-height: 1.4;
  font-weight: 800;
}

.b2b-client-photo-empty span {
  font-size: 10px;
  color: var(--n);
}

.b2b-client-photo-name {
  font-size: 10px;
  color: var(--gy);
  margin-top: 5px;
  word-break: break-word;
}

.b2b-client-photo-compact {
  width: 120px;
}

.b2b-client-photo-compact .b2b-client-photo-frame {
  width: 105px;
  height: 105px;
  position: relative;
}

.b2b-photo-inside-actions {
  position: absolute;
  left: 5px;
  right: 5px;
  bottom: 5px;
  display: flex;
  gap: 4px;
  justify-content: center;
}

.b2b-photo-mini-btn {
  background: rgba(13, 43, 78, 0.92);
  color: #ffffff;
  border: none;
  padding: 4px 6px;
  border-radius: 6px;
  font-size: 8.5px;
  font-weight: 900;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  line-height: 1;
}

.b2b-photo-mini-btn.camera {
  background: rgba(184, 134, 11, 0.95);
}

.b2b-photo-mini-btn input[type="file"] {
  position: absolute !important;
  inset: 0 !important;
  opacity: 0 !important;
  width: 100% !important;
  height: 100% !important;
  cursor: pointer !important;
}

.b2b-client-photo-compact .b2b-client-photo-empty {
  font-size: 21px;
  padding-bottom: 22px;
}

.b2b-client-photo-compact .b2b-client-photo-empty span {
  font-size: 9px;
}

.b2b-client-photo-compact .b2b-photo-actions {
  display: none !important;
}

