.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.metric {
  background: #f8f9fc;
  border: 1px solid var(--border);
  border-radius: 9px;
  padding: 12px;
  text-align: center;
}

.metric .v {
  font-size: 20px;
  font-weight: 900;
  color: var(--n);
}

.metric .l {
  font-size: 10px;
  color: var(--lg);
  font-weight: 800;
  text-transform: uppercase;
  margin-top: 4px;
}

/* tables */

.tbl-wrap {
  overflow-x: auto;
}

table.t {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

table.t th {
  background: #E7ECF2;
  color: var(--n);
  font-weight: 800;
  padding: 8px 10px;
  text-align: left;
  font-size: 10.5px;
  text-transform: uppercase;
  border-bottom: 2px solid var(--n);
}

table.t td {
  padding: 8px 10px;
  border-bottom: 1px solid #f0f3f8;
  vertical-align: middle;
}

table.t tr:nth-child(even) td {
  background: #f8f9fc;
}

table.t tr:hover td {
  background: #EEF3FF;
}

/* checkbox cards */

.check-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.check-card {
  border: 1.5px solid var(--border);
  padding: 10px;
  border-radius: 9px;
  background: #ffffff;
  cursor: pointer;
  font-weight: 700;
  color: var(--n);
}

.check-card:hover {
  border-color: var(--n);
  background: #F0F4FF;
}

.check-card input {
  margin-right: 7px;
}

/* medical flag cards */

.flag-grid {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.flag-opt {
  flex: 1;
  min-width: 220px;
  border: 2px solid var(--border);
  border-radius: 12px;
  padding: 16px 14px;
  background: #ffffff;
  cursor: pointer;
  transition: 0.15s;
  position: relative;
}

.flag-opt:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.flag-opt.active.green {
  border-color: var(--gr);
  background: #E8F5E9;
}

.flag-opt.active.orange {
  border-color: var(--or);
  background: #FFF3E0;
}

.flag-opt.active.red {
  border-color: var(--r);
  background: #FFEBEE;
}

/* IMPORTANT:
   This converts old emoji circle icons 🟢 🟠 🔴 into flag symbols using CSS.
   No need to change JS for this part. */
.flag-icon {
  font-size: 0 !important;
  line-height: 1;
  margin-bottom: 8px;
  height: 46px;
  display: flex;
  align-items: center;
}

.flag-icon::before {
  content: "⚑";
  font-size: 44px;
  line-height: 1;
  font-weight: 900;
  display: inline-block;
}

.flag-opt.green .flag-icon::before {
  color: var(--gr);
}

.flag-opt.orange .flag-icon::before {
  color: var(--or);
}

.flag-opt.red .flag-icon::before {
  color: var(--r);
}

/* Support if JS is changed to use life-flag-shape later */
.life-flag-shape {
  font-size: 44px;
  line-height: 1;
  font-weight: 900;
  margin-bottom: 8px;
}

.life-flag-shape.green-flag {
  color: var(--gr);
}

.life-flag-shape.orange-flag {
  color: var(--or);
}

.life-flag-shape.red-flag {
  color: var(--r);
}

.flag-title {
  font-size: 13px;
  font-weight: 900;
  color: var(--n);
  margin-bottom: 5px;
}

.flag-desc {
  font-size: 12px;
  color: var(--gy);
  line-height: 1.5;
}

.b2b-flag-inline-row {
  display: grid;
  grid-template-columns: 330px minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
  margin-bottom: 14px;
}

.b2b-flag-info {
  margin-bottom: 0 !important;
  height: 100%;
}

.b2b-flag-inline-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(150px, 1fr));
  gap: 10px;
}

.b2b-flag-inline-grid .flag-opt {
  min-width: 0;
  padding: 12px 12px;
}

.b2b-flag-inline-grid .life-flag-shape {
  font-size: 34px;
  margin-bottom: 5px;
}

.b2b-flag-inline-grid .flag-title {
  font-size: 12px;
  margin-bottom: 3px;
}

.b2b-flag-inline-grid .flag-desc {
  font-size: 10.5px;
  line-height: 1.35;
}

@media (max-width: 1000px) {
  .b2b-flag-inline-row {
    grid-template-columns: 1fr;
  }

  .b2b-flag-inline-grid {
    grid-template-columns: repeat(3, minmax(140px, 1fr));
  }
}

@media (max-width: 620px) {
  .b2b-flag-inline-grid {
    grid-template-columns: 1fr;
  }
}

.b2b-med-check-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 8px;
}

.b2b-med-check-card {
  border: 1.5px solid var(--border);
  border-radius: 8px;
  padding: 8px 9px;
  background: #ffffff;
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
  color: var(--n);
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  line-height: 1.25;
}

.b2b-med-check-card:hover {
  background: #F0F4FF;
  border-color: var(--n);
}

.b2b-med-check-card.red {
  border-left: 4px solid var(--r);
}

.b2b-med-check-card.orange {
  border-left: 4px solid var(--or);
}

.b2b-med-check-card input {
  margin: 0;
  flex-shrink: 0;
}

@media (max-width: 1000px) {
  .b2b-med-check-grid {
    grid-template-columns: repeat(2, minmax(150px, 1fr));
  }
}

@media (max-width: 520px) {
  .b2b-med-check-grid {
    grid-template-columns: 1fr;
  }
}

/* attachments */

.attach-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 12px;
}

.attach-slot {
  border: 2px dashed #cdd5e0;
  border-radius: 9px;
  padding: 16px 10px;
  text-align: center;
  cursor: pointer;
  background: #ffffff;
  position: relative;
  min-height: 112px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.attach-slot:hover,
.attach-slot.has-file {
  border-color: var(--n);
  background: #F0F4FF;
  border-style: solid;
}

.attach-slot input[type="file"] {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.attach-icon {
  font-size: 28px;
  margin-bottom: 5px;
}

.attach-name {
  font-size: 11px;
  color: var(--gy);
  word-break: break-all;
}

.add-pages-btn {
  border: 2px dashed var(--g);
  border-radius: 9px;
  padding: 16px 10px;
  text-align: center;
  cursor: pointer;
  color: var(--g);
  font-weight: 800;
  font-size: 13px;
  transition: 0.15s;
  background: #FFFDE7;
  min-height: 112px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.add-pages-btn:hover {
  background: var(--g);
  color: #ffffff;
}

/* signatures */

.signature-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.signature-box {
  background: #ffffff;
  border: 1.5px solid var(--border);
  border-radius: 10px;
  padding: 12px;
}

.signature-title {
  font-size: 11px;
  font-weight: 900;
  color: var(--n);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.signature-pad {
  width: 100%;
  height: 150px;
  border: 2px dashed #cdd5e0;
  border-radius: 8px;
  background: #ffffff;
  cursor: crosshair;
  touch-action: none;
}

.signature-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 9px;
  gap: 8px;
}

.signature-hint {
  font-size: 10.5px;
  color: var(--lg);
}

.sig-clear {
  background: #f0f0f0;
  border: 1px solid #dddddd;
  color: var(--gy);
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11px;
  cursor: pointer;
}

.sig-clear:hover {
  background: #e5e5e5;
}

/* empty, word count, toast */

.empty-box {
  padding: 28px;
  text-align: center;
  color: var(--lg);
  background: #ffffff;
  border: 1px dashed var(--border);
  border-radius: 10px;
}

.wc {
  font-size: 10px;
  text-align: right;
  font-weight: 700;
  margin-top: 2px;
}

.wc.ok {
  color: var(--gr);
}

.wc.warn {
  color: var(--or);
}

.wc.err {
  color: var(--r);
}



/* summary cards */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(160px, 1fr));
  gap: 12px;
}

.summary-box {
  background: #ffffff;
  border: 1px solid #dde3f0;
  border-radius: 12px;
  padding: 12px 14px;
  box-shadow: 0 2px 8px rgba(13, 43, 78, 0.06);
}

.summary-box .s-label {
  font-size: 10.5px;
  color: #6b7280;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .03em;
  margin-bottom: 5px;
}

.summary-box .s-value {
  font-size: 13px;
  color: #0D2B4E;
  font-weight: 800;
  word-break: break-word;
}

.summary-box.wide {
  grid-column: span 2;
}

.summary-box.full {
  grid-column: 1 / -1;
}

/* responsive */

@media (max-width: 900px) {
  .fg-4,
  .metrics {
    grid-template-columns: 1fr 1fr;
  }

  .check-grid {
    grid-template-columns: 1fr 1fr;
  }

  .summary-grid {
    grid-template-columns: repeat(2, minmax(140px, 1fr));
  }

  .summary-box.wide {
    grid-column: span 2;
  }
}

@media (max-width: 768px) {
  .fg-2,
  .fg-3,
  .fg-4,
  .metrics,
  .check-grid,
  .signature-grid {
    grid-template-columns: 1fr;
  }

  .life-hdr {
    flex-wrap: wrap;
    height: auto;
    padding: 10px 14px;
  }

  .life-right {
    width: 100%;
    margin-left: 0;
    justify-content: flex-start;
  }

  .wizard {
    top: 90px;
  }

  .profile-top {
    flex-direction: column;
    align-items: flex-start;
  }

  .search-big {
    flex-direction: column;
    align-items: stretch;
  }

  .btn-row {
    flex-direction: column;
    align-items: stretch !important;
  }

  .btn-row .btn-gy,
  .btn-row .btn-n,
  .btn-row .btn-gr {
    margin-left: 0 !important;
    margin-right: 0 !important;
  }

  .btn {
    justify-content: center;
  }
}

@media (max-width: 520px) {
  .summary-grid {
    grid-template-columns: 1fr;
  }

  .summary-box.wide,
  .summary-box.full {
    grid-column: 1;
  }
}

@media (max-width: 480px) {
  .main {
    padding: 14px 10px;
  }

  .card-body {
    padding: 14px;
  }

  .card-sub-hdr {
    margin-left: -14px;
    margin-right: -14px;
  }

  .wizard {
    padding: 12px 10px;
  }

  .wz-step {
    min-width: 95px;
  }
}

/* print */

@media print {
  .wizard,
  .hbtn,
  .btn-row,
  .toast-wrap {
    display: none !important;
  }

  .main {
    padding: 0;
  }

  .card {
    break-inside: avoid;
    box-shadow: none;
  }

  .life-hdr {
    position: static;
  }
}
