/* ============================================================
   LIFE GREEN THEME OVERRIDE
   Client Transfer Request Form
   ============================================================ */

:root{
    /* Main LIFE greens */
    --n:#145824;
    --n2:#1f6f31;

    /* Secondary accent */
    --g:#2f873d;
    --g2:#236d31;

    /* Status colours */
    --gr:#27843a;
    --r:#cf3d3d;
    --r2:#a72c2c;
    --or:#db842b;
    --teal:#27856d;

    /* Text */
    --gy:#5f6f64;
    --lg:#8b978e;

    /* Page / cards */
    --bg:#eef8f1;
    --card:#ffffff;
    --border:#d4e6d8;
    --text:#1c2b20;

    /* Shadow */
    --shadow:0 5px 20px rgba(20,88,36,.08);
}


/* ============================================================
   PAGE BACKGROUND
   ============================================================ */

html,
body{
    background:
        radial-gradient(
            circle at top left,
            rgba(62,145,78,.09),
            transparent 34%
        ),
        #eef8f1 !important;

    color:#1c2b20 !important;
}


.life-page{
    background:
        linear-gradient(
            180deg,
            #edf8f0 0%,
            #f5fbf6 100%
        ) !important;
}


/* ============================================================
   TOP HEADER
   ============================================================ */

.life-hdr{
    background:
        linear-gradient(
            90deg,
            #0d451c 0%,
            #145824 48%,
            #216b2e 100%
        ) !important;

    min-height:64px;

    border-bottom:1px solid rgba(255,255,255,.10);

    box-shadow:
        0 4px 16px rgba(12,69,28,.18) !important;
}


.life-logo{
    background:rgba(255,255,255,.13) !important;

    border:1px solid rgba(255,255,255,.24);

    color:#ffffff !important;

    border-radius:10px;
}


.life-title{
    color:#ffffff !important;
    font-weight:800;
}


.life-sub{
    color:rgba(255,255,255,.72) !important;
}


/* ============================================================
   HEADER BUTTONS
   ============================================================ */

.hbtn{
    background:rgba(255,255,255,.11) !important;

    border:1px solid rgba(255,255,255,.25) !important;

    color:#ffffff !important;

    border-radius:8px !important;

    transition:
        background .18s ease,
        transform .18s ease,
        border-color .18s ease;
}


.hbtn:hover{
    background:rgba(255,255,255,.20) !important;
    border-color:rgba(255,255,255,.40) !important;

    transform:translateY(-1px);
}


.hbtn.gold{
    background:#ffffff !important;
    color:#155b25 !important;

    border-color:#ffffff !important;

    font-weight:800;
}


.hbtn.gold:hover{
    background:#edf7ef !important;
}


/* ============================================================
   MAIN MODE TABS
   ============================================================ */

.life-mode-tabs{
    background:#ffffff !important;

    border-bottom:1px solid #d7e8da !important;

    box-shadow:
        0 3px 12px rgba(20,88,36,.05);
}


.life-mode-tab{
    color:#627166 !important;

    border-bottom-color:transparent !important;

    transition:
        background .18s ease,
        color .18s ease;
}


.life-mode-tab:hover{
    background:#f1f8f3 !important;
    color:#1e702f !important;
}


.life-mode-tab.active{
    color:#17622a !important;
    background:#edf7ef !important;

    border-bottom-color:#27843a !important;

    font-weight:900 !important;
}


.life-badge{
    background:#e8f5ea !important;
    color:#17622a !important;

    border:1px solid #cde5d2;
}


/* ============================================================
   WIZARD BAR
   ============================================================ */

.wizard{
    background:#ffffff !important;

    border-bottom:1px solid #d7e8da !important;

    box-shadow:
        0 3px 12px rgba(20,88,36,.05) !important;
}


.wz-step:not(:last-child)::after{
    background:#dce9df !important;
}


.wz-step.done:not(:last-child)::after,
.wz-step.active:not(:last-child)::after{
