    border-color:#2f873d !important;
    color:#ffffff !important;
}


.wz-step.active .wz-dot{
    background:#155b25 !important;
    border-color:#155b25 !important;
    color:#ffffff !important;

    box-shadow:
        0 0 0 5px rgba(39,132,58,.12) !important;
