.wz-label{
    color:#839087 !important;
}


.wz-step.done .wz-label{
    color:#27843a !important;
}


.wz-step.active .wz-label{
    color:#155b25 !important;
}


/* ============================================================
   APPROVAL FLOW BAR
   ============================================================ */

.approval-flow-bar{
