  function esc(value) {
    if (value === 0) value = "0";
    if (value === null || value === undefined) value = "";

    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function flt(value) {
    value = parseFloat(value);
    return isNaN(value) ? 0 : value;
  }

  function cint(value) {
    value = parseInt(value, 10);
    return isNaN(value) ? 0 : value;
  }

  function todayISO() {
    if (window.frappe && frappe.datetime) {
