  function showValidationPopup(title, errors) {
    const html = `
      <div style="line-height:1.8">
        ${errors.map(function (e) {
          return `<div>❌ ${esc(e)}</div>`;
        }).join("")}
      </div>
    `;

    if (window.frappe && frappe.msgprint) {
      frappe.msgprint({
        title: title || "Validation Required",
        indicator: "red",
        message: html
      });
    } else {
      alert(errors.join("\n"));
    }
  }


  function frappeCall(method, args) {
    return new Promise(function (resolve, reject) {
      if (!window.frappe || !frappe.call) {
        reject(new Error("Frappe is not available. Open this page after login."));
        return;
      }

      frappe.call({
        method: method,
        args: args || {},
        freeze: false,

        callback: function (r) {
          resolve(r.message);
        },

        error: function (r) {
          let msg = "Something went wrong";

          try {
            if (r && r._server_messages) {
              const arr = JSON.parse(r._server_messages);
              msg = JSON.parse(arr[0]).message || msg;
            } else if (r && r.message) {
              msg = r.message;
            }
          } catch (e) {}

          reject(new Error(msg));
        }
      });
    });
  }

