    (list || []).forEach(function (email) {
      email = String(email || "").trim();

      if (!email || email.indexOf("@") === -1) return;

      const key = email.toLowerCase();

      if (!seen[key]) {
        seen[key] = 1;
        out.push(email);
      }
    });

    return out;
  }

