    if (stage === "manager") {
      recipients = await getManagerMailRecipients();
      subject = "Branch Manager Approval Pending - " + docname;
    }

    if (stage === "audit") {
      recipients = getAuditMailRecipients();
      subject = "Audit Team Approval Pending - " + docname;
    }

    if (stage === "coo") {
      recipients = getCooMailRecipients();
      subject = "COO / Management Approval Pending - " + docname;
    }

    /*
      Do not send completed mail to all approvers.
      Final completion should not blast manager + audit + COO.
    */
    if (stage === "completed") {
      return;
    }

    await sendB2BMail(
      recipients,
      subject,
      buildTransferMailHtml(stage, docname),
      docname
    );
  }

  function getUserRoles() {
    if (window.frappe && frappe.user_roles) {
