  function hasAnyRole(words) {
    const roles = getUserRoles().map(function (r) {
      return String(r || "").toLowerCase();
    });

    return words.some(function (word) {
      const w = String(word || "").toLowerCase();

      return roles.some(function (role) {
        return role.indexOf(w) !== -1;
      });
    });
  }

  function isFullAccessUser() {
    const user = String((window.frappe && frappe.session && frappe.session.user) || "").toLowerCase();
    const fullName = String((window.frappe && frappe.session && frappe.session.user_fullname) || "").toLowerCase();

    return FULL_ACCESS_USERS.some(function (key) {
      key = String(key || "").toLowerCase();
      return user.indexOf(key) !== -1 || fullName.indexOf(key) !== -1;
    });
  }

  function canUseApprovalRole(role) {
    role = String(role || "").toLowerCase();

    if (isFullAccessUser()) {
      return true;
    }

    if (hasAnyRole(["system manager", "administrator"])) {
      return true;
    }

    if (role === "manager") {
      /*
        Branch Manager approval access is intentionally open for branch logins.
        Audit and COO are still locked to their fixed authorised user lists.
      */
      const user = currentUserId();

      if (!user || user.toLowerCase() === "guest") {
        return false;
      }

      return true;
    }

    if (role === "audit") {
      return isAllowedAuditUser();
    }

    if (role === "coo") {
      return isAllowedCooUser();
    }

    return false;
  }
    function detectUserLevel() {
    if (isFullAccessUser()) {
      return "ADMIN";
    }

    if (hasAnyRole(["system manager", "administrator"])) {
      return "ADMIN";
    }

    if (isAllowedCooUser()) {
      return "COO";
    }

    if (isAllowedAuditUser()) {
      return "AUDIT";
    }

    /*
      Branch users are allowed to open Branch Manager Approval.
      So normal logged-in branch users are treated as MANAGER level
      for this B2B approval page only.
