  function processStepClass(stageKey) {
    const manager = transferState.managerDecision || "";
    const audit = transferState.auditDecision || "";
    const final = transferState.finalApprovalStatus || "";

    if (stageKey === "submitted") {
      return "b2b-proc-done";
    }

    if (stageKey === "manager") {
      if (manager === "Rejected") return "b2b-proc-rejected";
      if (manager === "Approved") return "b2b-proc-done";
      return "b2b-proc-active";
    }

    if (stageKey === "audit") {
      if (manager === "Rejected") return "b2b-proc-stopped";
      if (audit === "Rejected") return "b2b-proc-rejected";
      if (audit === "Approved") return "b2b-proc-done";
      if (manager === "Approved") return "b2b-proc-active";
      return "b2b-proc-waiting";
    }

    if (stageKey === "coo") {
      if (manager === "Rejected" || audit === "Rejected") return "b2b-proc-stopped";
      if (final === "Rejected") return "b2b-proc-rejected";
      if (final === "Approved") return "b2b-proc-done";
      if (audit === "Approved") return "b2b-proc-active";
      return "b2b-proc-waiting";
    }

    if (stageKey === "branch_update") {
      if (manager === "Rejected" || audit === "Rejected" || final === "Rejected") {
        return "b2b-proc-stopped";
      }

      if (final === "Approved") return "b2b-proc-done";

      return "b2b-proc-waiting";
    }

    return "b2b-proc-waiting";
  }

  function processDot(stageKey, defaultNumber) {
    const manager = transferState.managerDecision || "";
    const audit = transferState.auditDecision || "";
    const final = transferState.finalApprovalStatus || "";

    if (stageKey === "submitted") return "✓";

    if (stageKey === "manager") {
      if (manager === "Approved") return "✓";
      if (manager === "Rejected") return "×";
      return defaultNumber;
    }

    if (stageKey === "audit") {
      if (audit === "Approved") return "✓";
      if (audit === "Rejected") return "×";
      return defaultNumber;
    }

    if (stageKey === "coo") {
      if (final === "Approved") return "✓";
      if (final === "Rejected") return "×";
      return defaultNumber;
    }

    if (stageKey === "branch_update") {
      if (final === "Approved") return "✓";
      if (manager === "Rejected" || audit === "Rejected" || final === "Rejected") return "×";
      return defaultNumber;
    }

    return defaultNumber;
  }

  function processSubText(stageKey) {
    const manager = transferState.managerDecision || "";
    const audit = transferState.auditDecision || "";
    const final = transferState.finalApprovalStatus || "";

    if (stageKey === "submitted") {
      return "Request created by branch user and submitted for approval.";
    }

    if (stageKey === "manager") {
      if (manager === "Approved") {
        return "Approved" + (transferState.branchManagerName ? " by " + esc(transferState.branchManagerName) : "");
      }

      if (manager === "Rejected") {
        return "Rejected" + (transferState.branchManagerName ? " by " + esc(transferState.branchManagerName) : "");
      }

      return "Approval Pending";
    }

    if (stageKey === "audit") {
      if (manager === "Rejected") return "Stopped because Branch Manager rejected.";

      if (audit === "Approved") {
        return "Approved" + (transferState.verifiedName ? " by " + esc(transferState.verifiedName) : "");
      }

      if (audit === "Rejected") {
        return "Rejected" + (transferState.verifiedName ? " by " + esc(transferState.verifiedName) : "");
      }

      if (manager === "Approved") return "Approval Pending";

      return "Waiting for Branch Manager approval.";
    }

    if (stageKey === "coo") {
      if (manager === "Rejected" || audit === "Rejected") return "Stopped due to rejection.";

      if (final === "Approved") return "Final approval completed.";
      if (final === "Rejected") return "Final approval rejected.";

      if (audit === "Approved") return "COO / Management Approval Pending";

      return "Waiting for Audit Team approval.";
    }

    if (stageKey === "branch_update") {
      if (final === "Approved") {
        return "Patient branch and Therapy Plan Branch + Transfer Branch updated.";
      }

      if (manager === "Rejected" || audit === "Rejected" || final === "Rejected") {
        return "Branch update stopped due to rejection.";
      }

      return "Will happen after COO / Management approval.";
    }

    return "";
  }

  function b2bProcessStep(stageKey, number, title) {
