async function fetchToBranchEmail() {
  /*
    403-safe version.

    Do not call:
    - frappe.client.get Branch
    - Address
    - Dynamic Link

    Branch Email comes from BRANCH_EMAIL_MAP.
  */

  const oldEmail = String(transferState.branchEmail || "").trim();

  const branchName = String(
    transferState.fromBranch ||
    transferState.loginBranch ||
    ""
  ).trim();

  if (!branchName) {
    return oldEmail;
