  function goToStep(step) {
    step = Number(step || 0);

    if (!canAccessStep(step)) {
      if (transferState.userLevel === "BRANCH") {
        toast("Branch users can access only the first 5 steps.", "r");
      } else if (transferState.userLevel === "MANAGER") {
        toast("Branch Manager can access Branch Manager approval only.", "r");
      } else if (transferState.userLevel === "AUDIT") {
        toast("Audit Team can access Audit approval only.", "r");
      } else if (transferState.userLevel === "COO") {
        toast("COO / Management can access final approval only.", "r");
      } else {
        toast("You do not have access to this step.", "r");
      }

      return;
    }

    if (
      transferState.finalApprovalStatus &&
      transferState.finalApprovalStatus !== "Pending" &&
      step !== 6
    ) {
      toast("Final decision already submitted. This request is locked.", "r");
      step = 6;
    }

    if (transferState.managerDecision === "Rejected" && step > 4) {
      toast("Branch Manager rejected this request. Further approval is blocked.", "r");
      step = 4;
    }

    if (transferState.auditDecision === "Rejected" && step > 5) {
      toast("Audit Team rejected this request. COO approval is blocked.", "r");
      step = 5;
    }

    if (step > 0 && !selectedClient) {
      toast("Please select or open a client request first.", "r");
      return;
    }


    if (step > 2 && !transferState.toBranch) {
      toast("Please select Transfer To Branch first.", "r");
      return;
    }

    if (step === 5 && transferState.managerDecision !== "Approved") {
      toast("Branch Manager approval is required before Audit Team approval.", "r");
      return;
    }

    if (step === 6 && transferState.auditDecision !== "Approved") {
      toast("Audit Team approval is required before COO approval.", "r");
      return;
    }

    currentWizardStep = step;
    switchMode(0, true);
    setApprovalFlowBarVisibility(currentWizardStep);

    document.querySelectorAll(".page").forEach(function (page, index) {
      page.classList.toggle("active", index === step);
    });

    document.querySelectorAll(".wz-step").forEach(function (item, index) {
      item.classList.remove("active", "done");

      const dot = $("wd-" + index);

      if (index < step) {
        item.classList.add("done");
        if (dot) dot.textContent = "✓";
      } else if (index === step) {
        item.classList.add("active");
        if (dot) dot.textContent = index + 1;
      } else {
        if (dot) dot.textContent = index + 1;
      }
    });
        if (step === 1) renderProfile();
    if (step === 2) renderTransferDetails();
    if (step === 3) renderDocuments();

    if (step === 4) {
      setupWizardByRole();

      if (
        createdDocName &&
        (transferState.userLevel === "MANAGER" || transferState.userLevel === "ADMIN")
      ) {
        renderManagerApproval();
      } else if (createdDocName && transferState.userLevel === "BRANCH") {
        renderBranchSubmittedMessage();
      } else {
        renderRemarks();
      }
    }

    if (step === 5) {
      renderAuditApproval();
    }

    if (step === 6) {
      renderCOOApproval();
    }

    updateApprovalFlowBar();

    window.scrollTo({ top: 0, behavior: "smooth" });
  }

