function getPatientBranch(p) {
  p = p || {};

  /*
    Correct rule:
    Current branch must come from main Patient branch fields first.

    Do NOT prefer Brnch List first.
    Brnch List is only branch history / multi-branch access.
  */

  const directBranch =
    cleanBranchValue(p.custom_branch) ||
    cleanBranchValue(p.branch_name) ||
    cleanBranchValue(p.custom_current_branch) ||
    cleanBranchValue(p.current_branch) ||
    cleanBranchValue(p.branch);

  if (directBranch) {
    return directBranch;
  }

  /*
    Fallback only if main Patient branch fields are empty.
  */
  const possibleTables = [
    p.custom_branch_list,
    p.custom_brnch_list,
    p.branch_list,
    p.custom_branches
  ];

  for (let i = 0; i < possibleTables.length; i++) {
    const rows = possibleTables[i];

    if (!Array.isArray(rows) || !rows.length) continue;

    for (let j = rows.length - 1; j >= 0; j--) {
      const row = rows[j] || {};

      const rowBranch =
        cleanBranchValue(row.branch) ||
        cleanBranchValue(row.branch_name) ||
        cleanBranchValue(row.custom_branch) ||
        cleanBranchValue(row.from_branch) ||
        cleanBranchValue(row.current_branch);

      if (rowBranch) {
        return rowBranch;
      }
    }
  }

  return "";
}

