async function selectClient(clientName) {
  const loadToken = ++activeClientLoadToken;

  try {
    resetTransferDraftForNewClient();
    selectedClient = null;

    showClientProfileLoading(clientName);

    const patient = await frappeCall("frappe.client.get", {
      doctype: "Patient",
      name: clientName
    });

    if (loadToken !== activeClientLoadToken) return;

    selectedClient = normalizePatient(patient);

    /*
      From Branch must come from the selected client's actual branch only.
      Do not fallback to login branch.
    */
    transferState.fromBranch = selectedClient.branch || "";

    if (!transferState.fromBranch) {
      showValidationPopup("Client Branch Missing", [
        "Unable to identify the selected client's current branch.",
        "Please check the Patient branch / branch list before creating a transfer request."
      ]);
      return;
    }

      transferState.toBranch = "";
      transferState.branchEmail = "";
      transferState.requestDate = todayISO();

      await Promise.all([
      loadStaffForBranch(transferState.fromBranch),
      fetchInvoiceSummary(clientName),
      fetchTherapyPlans(clientName),
      fetchLastVisitGap(clientName)
     ]);

      await fetchToBranchEmail();

