  async function fetchInvoiceSummary(clientName) {
    transferState.invoices = [];
    transferState.totalBilled = 0;
    transferState.totalReceived = 0;
    transferState.balanceDue = 0;

    try {
      const invoices = await getList(
        "Sales Invoice",
        [
          "name",
          "posting_date",
          "status",
          "grand_total",
          "rounded_total",
          "outstanding_amount",
          "docstatus"
        ],
        [
          ["patient", "=", clientName],
          ["docstatus", "!=", 2],
          ["is_return", "=", 0]
        ],
        [],
        "posting_date desc",
        50
      );

      transferState.invoices = invoices || [];

      transferState.invoices.forEach(function (inv) {
        const total = flt(inv.rounded_total || inv.grand_total || 0);
        const outstanding = flt(inv.outstanding_amount || 0);
        const paid = Math.max(total - outstanding, 0);

        inv._paid = paid;
        inv._balance = outstanding;

        transferState.totalBilled += total;
        transferState.totalReceived += paid;
        transferState.balanceDue += outstanding;
      });
    } catch (e) {
      void 0;
      transferState.invoices = [];
    }
  }

  async function fetchTherapyPlans(clientName) {
    transferState.plans = [];

    try {
      const plans = await getList(
        "Therapy Plan",
        [
          "name",
          "patient",
          "patient_name",
          "status",
          "start_date",
          "creation",
          "modified"
        ],
        [["patient", "=", clientName]],
        [],
        "modified desc",
        50
      );

      const finalPlans = [];

      for (const p of plans || []) {
        try {
          const fullPlan = await frappeCall("frappe.client.get", {
            doctype: "Therapy Plan",
            name: p.name
          });

          const rows =
            fullPlan.therapy_plan_details ||
            fullPlan.therapy_plan_detail ||
            fullPlan.therapy_plans ||
            fullPlan.therapy_plan_table ||
            [];

          if (rows.length) {
            rows.forEach(function (row) {
              const therapyName =
                row.therapy_type ||
                row.therapy ||
                row.service ||
                row.service_name ||
                row.item_name ||
                row.item_code ||
                "—";

              const total =
                row.no_of_sessions ||
                row.sessions ||
                row.total_sessions ||
                row.qty ||
                row.quantity ||
                0;

              const completed =
                row.sessions_completed ||
                row.completed_sessions ||
                row.total_sessions_completed ||
                row.completed ||
                row.delivered_sessions ||
                row.availed_quantity ||
                0;

              finalPlans.push({
                plan_id: p.name,
                therapy_name: therapyName,
                status: p.status || "—",
                start_date: p.start_date || p.creation,
                total_sessions: total,
                total_sessions_completed: completed,
                balance_sessions: Math.max(cint(total) - cint(completed), 0)
              });
            });
          } else {
            finalPlans.push({
              plan_id: p.name,
              therapy_name: fullPlan.therapy_plan_template || "Therapy details not found",
              status: p.status || "—",
              start_date: p.start_date || p.creation,
              total_sessions: fullPlan.total_sessions || "—",
              total_sessions_completed: "—",
              balance_sessions: "—"
            });
          }
        } catch (e) {
          finalPlans.push({
            plan_id: p.name,
            therapy_name: p.name,
            status: p.status || "—",
            start_date: p.start_date || p.creation,
            total_sessions: "—",
            total_sessions_completed: "—",
            balance_sessions: "—"
          });
        }
      }

      transferState.plans = finalPlans;
    } catch (e) {
      void 0;
      transferState.plans = [];
    }
  }
    async function fetchLastVisitGap(clientName) {
    transferState.attendanceGap = 0;
    transferState.requiresAudit = false;
    transferState.lastVisit = "";

    try {
      const sessions = await getList(
        "Therapy Session",
        ["name"],
        [
          ["patient", "=", clientName],
          ["docstatus", "!=", 2]
        ],
        [],
        "modified desc",
