      );

      if (!sessions || !sessions.length || !sessions[0].name) {
        return;
      }

      const sessionDoc = await frappeCall("frappe.client.get", {
        doctype: "Therapy Session",
        name: sessions[0].name
      });

      const last =
        sessionDoc.start_date ||
        sessionDoc.session_date ||
        sessionDoc.date ||
        sessionDoc.appointment_date ||
        sessionDoc.creation ||
        "";

      if (last) {
        transferState.lastVisit = String(last).slice(0, 10);

        if (window.frappe && frappe.datetime) {
          transferState.attendanceGap = frappe.datetime.get_day_diff(
            todayISO(),
            transferState.lastVisit
          );
        }

        transferState.requiresAudit = transferState.attendanceGap >= 365;
      }
    } catch (e) {
      void 0;
    }
  }

  function fileUrlToAbsolute(url) {
  url = String(url || "").trim();

  if (!url) return "";

  if (url.indexOf("http://") === 0 || url.indexOf("https://") === 0) {
    return url;
  }

  return url;
}

