let b2bCameraStream = null;

async function openClientCamera() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    frappe.msgprint("Camera is not supported in this browser.");
    return;
  }

  try {
    b2bCameraStream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: "environment"
      },
      audio: false
    });

    const modal = document.createElement("div");
    modal.id = "b2b-camera-modal";
    modal.innerHTML = `
      <div class="b2b-camera-backdrop">
        <div class="b2b-camera-box">
          <div class="b2b-camera-title">Capture Client Photo</div>

          <video id="b2b-camera-video" autoplay playsinline></video>

          <div class="b2b-camera-actions">
            <button type="button" class="btn btn-gy" onclick="B2B.closeClientCamera()">
              Cancel
            </button>

            <button type="button" class="btn btn-g" onclick="B2B.captureFromCamera()">
              📷 Capture
            </button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(modal);

    const video = document.getElementById("b2b-camera-video");
    video.srcObject = b2bCameraStream;
  } catch (e) {
    void 0;
    frappe.msgprint("Unable to open camera. Please allow camera permission in browser.");
  }
}

function closeClientCamera() {
  if (b2bCameraStream) {
    b2bCameraStream.getTracks().forEach(function (track) {
      track.stop();
    });
  }

  b2bCameraStream = null;

  const modal = document.getElementById("b2b-camera-modal");
  if (modal) {
    modal.remove();
  }
}

function captureFromCamera() {
  const video = document.getElementById("b2b-camera-video");

  if (!video) {
    return;
  }

  const canvas = document.createElement("canvas");
  canvas.width = video.videoWidth || 640;
  canvas.height = video.videoHeight || 480;

  const ctx = canvas.getContext("2d");
  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

  canvas.toBlob(function (blob) {
    if (!blob) {
      frappe.msgprint("Unable to capture photo.");
      return;
    }

    const file = new File(
      [blob],
      "client-photo-" + Date.now() + ".jpg",
      { type: "image/jpeg" }
    );

    transferState.clientPhoto = file;
    transferState.clientPhotoName = file.name;
    transferState.clientPhotoUrl = URL.createObjectURL(file);

    closeClientCamera();
    renderProfile();
  }, "image/jpeg", 0.9);
}

async function uploadClientPhoto(docname) {
  if (!transferState.clientPhoto) return;

  const formData = new FormData();

  formData.append("file", transferState.clientPhoto);
  formData.append("doctype", DOCTYPE);
  formData.append("docname", docname);
  formData.append("fieldname", "client_photo");
  formData.append("is_private", "1");

  try {
    const res = await fetch("/api/method/upload_file", {
      method: "POST",
      headers: {
        "X-Frappe-CSRF-Token": frappe.csrf_token
      },
      body: formData
    });

    const data = await res.json();
    const fileUrl =
      data &&
      data.message &&
      data.message.file_url
        ? data.message.file_url
        : "";

    if (fileUrl) {
      transferState.clientPhotoUrl = fileUrl;

      await frappeCall("frappe.client.set_value", {
        doctype: DOCTYPE,
        name: docname,
        fieldname: {
          client_photo: fileUrl
        }
      });
    }
  } catch (e) {
    void 0;
  }
}

