  async function validateTransferDetails() {
    updateTransferDraft();

    const errors = [];
    const today = todayISO();

    if (!transferState.toBranch || !transferState.toBranch.trim()) {
      errors.push("Transfer To Branch is mandatory.");
    }

    if (
      transferState.toBranch &&
      transferState.fromBranch &&
      transferState.toBranch.trim() === transferState.fromBranch.trim()
    ) {
      errors.push("Transfer From Branch and Transfer To Branch cannot be same.");
    }

    if (!transferState.preferredDate) {
      errors.push("Preferred Start At New Branch is mandatory.");
    }

    if (transferState.preferredDate && transferState.preferredDate < today) {
      errors.push("Preferred Start At New Branch cannot be a back date.");
    }

    if (!transferState.reason || !transferState.reason.trim()) {
      errors.push("Reason For Transfer is mandatory.");
    }

    if (wordCount(transferState.reason) > 400) {
      errors.push("Reason For Transfer should be within 400 words.");
    }

    if (wordCount(transferState.detailedReason) > 400) {
      errors.push("Other / Detailed Reason should be within 400 words.");
    }

    if (errors.length) {
      showValidationPopup("Please complete transfer details", errors);
      return;
    }

    try {
      await fetchToBranchEmail();
    } catch (e) {
      void 0;
      transferState.branchEmail = "";
    }

    goToStep(3);
  }

