  const saved =
    type === "red"
      ? transferState.redMedicalConditions || {}
      : transferState.orangeMedicalConditions || {};

  return list.map(function (item) {
    const checked = saved[item.key] ? "checked" : "";

    return `
      <label class="b2b-med-check-card ${type}">
        <input
