function updateMedicalConditions() {
  transferState.redMedicalConditions = {};
  transferState.orangeMedicalConditions = {};

  document.querySelectorAll("[data-med-risk]").forEach(function (el) {
    const risk = el.getAttribute("data-med-risk");
    const key = el.getAttribute("data-med-key");

    if (!key) return;

    if (risk === "red") {
      transferState.redMedicalConditions[key] = el.checked ? 1 : 0;
    }

    if (risk === "orange") {
      transferState.orangeMedicalConditions[key] = el.checked ? 1 : 0;
    }
  });

  autoSetMedicalFlagFromConditions();
  renderDocuments();
}

function autoSetMedicalFlagFromConditions() {
  const hasRed = Object.keys(transferState.redMedicalConditions || {}).some(function (key) {
    return transferState.redMedicalConditions[key];
  });

  const hasOrange = Object.keys(transferState.orangeMedicalConditions || {}).some(function (key) {
    return transferState.orangeMedicalConditions[key];
  });

  if (hasRed) {
    transferState.medFlag = "red";
    return;
  }

  if (hasOrange) {
    transferState.medFlag = "orange";
    return;
