  function signatureBox(key, label) {
    return `
      <div class="signature-box">
        <div class="signature-title">${esc(label)} <span class="req">*</span></div>

        <canvas class="signature-pad" id="sig-${key}"></canvas>

        <div class="signature-actions">
          <span class="signature-hint">Draw signature inside the box</span>
          <button type="button" class="sig-clear" onclick="B2B.clearSignature('${key}')">Clear</button>
