  function initSignaturePad(key) {
    const canvas = $("sig-" + key);
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = 150;

    const ctx = canvas.getContext("2d");
    ctx.lineWidth = 2;
    ctx.lineCap = "round";
    ctx.strokeStyle = "#0D2B4E";

    if (transferState.signatures[key]) {
      const img = new Image();
      img.onload = function () {
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      };
      img.src = transferState.signatures[key];
    }

    let drawing = false;

    function getPos(e) {
      const r = canvas.getBoundingClientRect();
      const point = e.touches ? e.touches[0] : e;

      return {
        x: point.clientX - r.left,
        y: point.clientY - r.top
      };
    }

    function start(e) {
      e.preventDefault();
      drawing = true;

      const p = getPos(e);
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
    }

    function move(e) {
      if (!drawing) return;

      e.preventDefault();

      const p = getPos(e);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();

      transferState.signatures[key] = canvas.toDataURL("image/png");
    }

    function end() {
      if (!drawing) return;

      drawing = false;
      transferState.signatures[key] = canvas.toDataURL("image/png");
    }

    canvas.addEventListener("mousedown", start);
    canvas.addEventListener("mousemove", move);
    canvas.addEventListener("mouseup", end);
    canvas.addEventListener("mouseleave", end);

    canvas.addEventListener("touchstart", start, { passive: false });
    canvas.addEventListener("touchmove", move, { passive: false });
    canvas.addEventListener("touchend", end);
  }

  function clearSignature(key) {
    const canvas = $("sig-" + key);
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    transferState.signatures[key] = "";
  }

