 async function uploadSingleDocumentFile(file, docname) {
  if (!file || !docname) return null;

  const formData = new FormData();

  formData.append("file", file);
  formData.append("doctype", DOCTYPE);
  formData.append("docname", docname);
  formData.append("is_private", "1");

  const response = await fetch("/api/method/upload_file", {
    method: "POST",
    headers: {
      "X-Frappe-CSRF-Token": frappe.csrf_token
    },
    body: formData
  });

  const data = await response.json();
  const msg = data.message || {};

  if (!msg.file_url) {
    throw new Error("File upload failed: " + (file.name || ""));
  }

  return {
    file_name: msg.file_name || file.name || "",
    file_url: msg.file_url || "",
    name: msg.name || ""
  };
}

async function uploadRequestDocumentsAndSaveTable(docname) {
  if (!docname) return;

  ensureAttachmentRows();

  const rows = [];

  for (let i = 0; i < transferState.files.length; i++) {
    const file = transferState.files[i];

    if (!file) continue;

    const uploaded = await uploadSingleDocumentFile(file, docname);

    rows.push({
      client_card: pageLabel(i),
      attach_pdf_bill: uploaded.file_url || "",
      file_name: uploaded.file_name || file.name || "",
      required: isRequiredAttachmentRow(i) ? 1 : 0,
      row_no: i + 1
    });
  }

  const doc = await frappeCall("frappe.client.get", {
    doctype: DOCTYPE,
    name: docname
  });

  doc.attached_files = rows;

  await frappeCall("frappe.client.save", {
    doc: doc
  });
}
