  function b2bStepStatusFromRow(row) {
    const status = getRequestStatus(row || {});

    const out = {
      submitted: "Approved",
      manager: "Pending",
      audit: "Waiting",
      coo: "Waiting",
      transfer: "Waiting"
    };

    if (status === STAGE.MANAGER_REJECTED) {
      out.manager = "Rejected";
      out.audit = "Blocked";
      out.coo = "Blocked";
      out.transfer = "Blocked";
      return out;
    }

    if (
      status === STAGE.AUDIT_PENDING ||
      status === STAGE.COO_PENDING ||
      status === STAGE.COMPLETED ||
      status === STAGE.AUDIT_REJECTED ||
      status === STAGE.COO_REJECTED
    ) {
      out.manager = "Approved";
    }

    if (status === STAGE.AUDIT_REJECTED) {
      out.audit = "Rejected";
      out.coo = "Blocked";
      out.transfer = "Blocked";
      return out;
    }

    if (
      status === STAGE.COO_PENDING ||
      status === STAGE.COMPLETED ||
      status === STAGE.COO_REJECTED
    ) {
      out.audit = "Approved";
    }

    if (status === STAGE.COO_REJECTED) {
      out.coo = "Rejected";
      out.transfer = "Blocked";
      return out;
    }

    if (status === STAGE.COMPLETED || row.final_approval_status === "Approved") {
      out.coo = "Approved";
      out.transfer = "Approved";
      return out;
    }

    if (status === STAGE.AUDIT_PENDING) {
      out.audit = "Pending";
    }

    if (status === STAGE.COO_PENDING) {
      out.coo = "Pending";
    }

    return out;
  }

