    formData.append("docname", docname);
    formData.append("fieldname", fieldname);
    formData.append("is_private", "1");

    try {
      await fetch("/api/method/upload_file", {
        method: "POST",
        headers: {
          "X-Frappe-CSRF-Token": frappe.csrf_token
        },
        body: formData
