    async function managerFinalDecision(action) {
    if (!canUseApprovalRole("manager")) {
      showValidationPopup("Access Denied", [
        "Branch users are allowed for Branch Manager Approval, but your login is not valid."
      ]);
      return;
    }

    updateBranchManager();

if (!transferState.branchManagerName) {
  transferState.branchManagerName =
    transferState.loginEmployeeName ||
    currentUserFullName() ||
    currentUserId() ||
    "";
}

if (!transferState.branchManager) {
  transferState.branchManager =
    transferState.loginEmployee ||
    currentUserId() ||
    "";
}

action = String(action || "").trim();

transferState.bmRemarks = val("bm-remarks");

    const errors = [];

    if (!createdDocName) {
      errors.push("Create request first before Branch Manager approval.");
    }

    if (!["Approve", "Reject"].includes(action)) {
      errors.push("Invalid Branch Manager action.");
    }

    if (!transferState.branchManagerName) {
      errors.push("Branch Manager name is mandatory.");
    }

    if (!transferState.bmRemarks.trim()) {
      errors.push("Branch Manager remarks are mandatory.");
    }

    if (wordCount(transferState.bmRemarks) > 100) {
      errors.push("Branch Manager remarks should be within 100 words.");
    }

    if (!transferState.signatures.branchManager) {
      errors.push("Branch Manager signature is mandatory.");
    }

    if (errors.length) {
      showValidationPopup("Please complete Branch Manager approval", errors);
      return;
    }

    const isApprove = action === "Approve";

    const updateDoc = {
      current_tab_step: isApprove ? 6 : 5,

      approval_display_status: isApprove
        ? STAGE.AUDIT_PENDING
        : STAGE.MANAGER_REJECTED,

      audit_status: isApprove ? "Pending" : "Rejected",
      final_approval_status: isApprove ? "Pending" : "Rejected",

      branch_manager_id: transferState.branchManager || "",
     cmname: transferState.branchManagerName || "",
     cmreason: transferState.bmRemarks,
     cmsignature: transferState.signatures.branchManager,
     cmdate: todayISO(),

      remarks: isApprove
        ? STAGE.AUDIT_PENDING
        : STAGE.MANAGER_REJECTED,

      detailed_reason_mandatory__write_in_own_words:
        safeDetailedReasonText()
    };

    try {
      await frappeCall("frappe.client.set_value", {
        doctype: DOCTYPE,
        name: createdDocName,
        fieldname: updateDoc
      });

      await saveOptionalStageTimestamp("custom_manager_decision_at");

      if (isApprove) {
        await sendTransferStageMail("audit", createdDocName);
      }

      transferState.managerDecision = isApprove ? "Approved" : "Rejected";
      transferState.managerSubmitted = 1;

      updateApprovalFlowBar();

      frappe.msgprint({
        title: isApprove ? "Branch Manager Approved" : "Branch Manager Rejected",
        indicator: isApprove ? "green" : "red",
        message: isApprove
          ? "Branch Manager approval saved. Request moved to Audit Team."
          : "Branch Manager rejection saved. Request is stopped."
      });

      toast(
        isApprove ? "Moved To Audit Team" : "Branch Manager Rejected",
        isApprove ? "g" : "r"
      );

      if (
        isApprove &&
