  // ============================================================
  // LIFE B2B - optional exact approval timestamp helper
  // These fields are optional. If they exist, exact timing is saved.
  // If they do not exist, approval still works and timeline falls back
  // to the existing Date / Datetime fields.
  // ============================================================

  function b2bNowDbDateTime() {
    try {
      if (
        window.frappe &&
        frappe.datetime &&
        typeof frappe.datetime.now_datetime === "function"
      ) {
        return frappe.datetime.now_datetime();
      }
    } catch (e) {}

    const d = new Date();

    function z(n) {
      return String(n).padStart(2, "0");
    }

    return (
      d.getFullYear() +
      "-" +
      z(d.getMonth() + 1) +
      "-" +
      z(d.getDate()) +
      " " +
      z(d.getHours()) +
      ":" +
      z(d.getMinutes()) +
      ":" +
      z(d.getSeconds())
    );
  }

  async function saveOptionalStageTimestamp(fieldname) {
    if (!createdDocName || !fieldname) return "";

    const nowValue = b2bNowDbDateTime();

    try {
      const obj = {};
      obj[fieldname] = nowValue;

      await frappeCall("frappe.client.set_value", {
        doctype: DOCTYPE,
        name: createdDocName,
        fieldname: obj
      });

      return nowValue;
    } catch (e) {
      void 0;

      return "";
    }
  }

