    async function auditFinalDecision(action) {
    if (!canUseApprovalRole("audit")) {
      showValidationPopup("Access Denied", [
        "Only authorised Audit Team users can approve this stage."
      ]);
      return;
    }

    updateVerificationDraft();

    action = String(action || "").trim();

    const errors = [];

    if (!createdDocName) {
      errors.push("Open request first before Audit Team approval.");
    }

    if (transferState.managerDecision !== "Approved") {
      errors.push("Branch Manager approval is required before Audit Team approval.");
    }

    if (!["Approve", "Reject"].includes(action)) {
      errors.push("Invalid Audit Team action.");
    }

    if (!transferState.verifiedName) {
      errors.push("Audit Team name is mandatory.");
    }

    if (!transferState.verificationRemarks.trim()) {
      errors.push("Audit Team remarks are mandatory.");
    }

    if (wordCount(transferState.verificationRemarks) > 100) {
      errors.push("Audit Team remarks should be within 100 words.");
    }

    if (!transferState.signatures.verifier) {
      errors.push("Audit Team signature is mandatory.");
    }

    if (errors.length) {
      showValidationPopup("Please complete Audit Team approval", errors);
      return;
    }

    const isApprove = action === "Approve";

    const updateDoc = {
      current_tab_step: isApprove ? 7 : 6,

      approval_display_status: isApprove
        ? STAGE.COO_PENDING
        : STAGE.AUDIT_REJECTED,

      audit_status: isApprove ? "Approved" : "Rejected",
      final_approval_status: isApprove ? "Pending" : "Rejected",

      audit_verified_by: transferState.verifiedName,
      audit_verified_date: transferState.verifiedDate || todayISO(),
      audit_remarks: transferState.verificationRemarks,
      audit_signature: transferState.signatures.verifier,

      remarks: isApprove
        ? STAGE.COO_PENDING
        : STAGE.AUDIT_REJECTED,

      detailed_reason_mandatory__write_in_own_words:
        safeDetailedReasonText()
    };

    try {
      await frappeCall("frappe.client.set_value", {
        doctype: DOCTYPE,
        name: createdDocName,
        fieldname: updateDoc
      });

      await saveOptionalStageTimestamp("custom_audit_decision_at");

      if (isApprove) {
        await sendTransferStageMail("coo", createdDocName);
      }

      transferState.auditDecision = isApprove ? "Approved" : "Rejected";
      transferState.auditSubmitted = 1;

      updateApprovalFlowBar();

      frappe.msgprint({
        title: isApprove ? "Audit Team Approved" : "Audit Team Rejected",
        indicator: isApprove ? "green" : "red",
        message: isApprove
          ? "Audit Team approval saved. Request moved to COO / Final Approval."
          : "Audit Team rejection saved. Request is stopped."
      });

      toast(
        isApprove ? "Moved To COO / Final Approval" : "Audit Team Rejected",
        isApprove ? "g" : "r"
      );

      if (
        isApprove &&
        (transferState.userLevel === "COO" || transferState.userLevel === "ADMIN")
      ) {
        goToStep(6);
      } else {
        renderAuditApproval();
      }
    } catch (e) {
      showValidationPopup("Audit Team Approval Failed", [
        e.message || "Unable to save Audit Team approval."
      ]);
    }
  }

