  function b2bIsDateOnly(value) {
    return /^\d{4}-\d{2}-\d{2}$/.test(String(value || "").trim());
  }

  function b2bParseTimelineDate(value) {
    const raw = String(value || "").trim();

    if (!raw) return null;

    try {
      const normalized = raw.indexOf("T") !== -1
        ? raw
        : raw.replace(" ", "T");

      const d = new Date(normalized);

      return isNaN(d.getTime()) ? null : d;
    } catch (e) {
      return null;
    }
  }

  function b2bFmtTimelineDateTime(value) {
    const raw = String(value || "").trim();

    if (!raw) return "—";

    const d = b2bParseTimelineDate(value);

    if (!d) return raw;

    const months = [
      "Jan", "Feb", "Mar", "Apr", "May", "Jun",
      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
    ];

    const dd = String(d.getDate()).padStart(2, "0");
    const mon = months[d.getMonth()];
    const yy = String(d.getFullYear()).slice(-2);

    if (b2bIsDateOnly(raw)) {
      return dd + "-" + mon + "-" + yy;
    }

    let hh = d.getHours();
    const mm = String(d.getMinutes()).padStart(2, "0");
    const ap = hh >= 12 ? "PM" : "AM";

    hh = hh % 12;
    if (!hh) hh = 12;

    return (
      dd + "-" + mon + "-" + yy +
      " " + hh + ":" + mm + " " + ap
    );
  }

  function b2bTimelineDuration(startValue, endValue) {
    const sRaw = String(startValue || "").trim();
    const eRaw = String(endValue || "").trim();

    if (!sRaw || !eRaw) return "—";

    let s = null;
    let e = null;

    /*
      Old records may contain only YYYY-MM-DD.
      For those records, 12:00 AM is used as fallback.
      New records with exact Datetime values use the real time.
    */
    if (b2bIsDateOnly(sRaw)) {
      s = new Date(sRaw + "T00:00:00");
    } else {
      s = b2bParseTimelineDate(sRaw);
    }

    if (b2bIsDateOnly(eRaw)) {
      e = new Date(eRaw + "T00:00:00");
    } else {
      e = b2bParseTimelineDate(eRaw);
    }

    if (!s || !e || isNaN(s.getTime()) || isNaN(e.getTime())) {
      return "—";
    }

    let totalSeconds = Math.floor(
      (e.getTime() - s.getTime()) / 1000
    );

    if (totalSeconds < 0) return "—";

    const days = Math.floor(totalSeconds / 86400);
    totalSeconds = totalSeconds % 86400;

    const hours = Math.floor(totalSeconds / 3600);
    totalSeconds = totalSeconds % 3600;

    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;

    /*
      Under 24 hours:
        14h 17m 50s

      24 hours or more:
        1d 02h 05m 10s
        8d 23h 12m 00s
    */
    if (days > 0) {
      return (
        days + "d " +
        String(hours).padStart(2, "0") + "h " +
        String(minutes).padStart(2, "0") + "m " +
        String(seconds).padStart(2, "0") + "s"
      );
    }

    return (
      hours + "h " +
      String(minutes).padStart(2, "0") + "m " +
      String(seconds).padStart(2, "0") + "s"
    );
  }

  function b2bTimelinePill(status) {
    const s = String(status || "Pending");

    let bg = "#fff4cc";
    let fg = "#8a6400";

    if (
      s === "Approved" ||
      s === "Completed" ||
      s === "Submitted"
    ) {
      bg = "#e7f8ec";
      fg = "#087a37";
    }

    if (s === "Rejected" || s === "Stopped") {
      bg = "#fde7e7";
      fg = "#a50000";
    }

    return `
      <span style="
        display:inline-block;
        padding:4px 10px;
        border-radius:14px;
        background:${bg};
        color:${fg};
        font-size:11px;
        font-weight:800;
        white-space:nowrap;
      ">
        ${esc(s)}
      </span>
    `;
  }

