  async function hydrateApprovalTimeline(row, panel) {
    if (!row || !panel) return;

    const host = panel.querySelector(".b2b-approval-timeline-host");

    if (!host) return;

    host.innerHTML = approvalTimelineTableHtml(row);

    try {
      const fullDoc = await frappeCall("frappe.client.get", {
        doctype: DOCTYPE,
        name: row.name
      });

      if (!fullDoc) return;

      const merged = Object.assign({}, row, fullDoc);

      host.innerHTML = approvalTimelineTableHtml(merged);
    } catch (e) {
      void 0;
    }
  }

  function renderTransferRequestDetail(row, panel, approvalMode) {
