  function getPatientIdFromRequestDoc(doc) {
    doc = doc || {};

    return String(
      doc.client_full_name ||
      doc.client_id__crm_no ||
      doc.client ||
      ""
    ).trim();
  }

  function openTransferRequestFromList(docname, targetStep) {
  if (!docname) return;

  frappeCall("frappe.client.get", {
    doctype: DOCTYPE,
    name: docname
  })
    .then(function (doc) {
      doc = doc || {};

      loadRequestDocIntoState(doc);

      if (transferState.fromBranch) {
        return loadStaffForBranch(transferState.fromBranch).then(function () {
          /*
            loadStaffForBranch() loads employee options,
            but it clears saved branch staff and manager names.
            So load the saved request values again after staff list loading.
          */
          loadRequestDocIntoState(doc);
          return doc;
        });
      }

      return doc;
    })
    .then(function (doc) {
      const patientId = getPatientIdFromRequestDoc(doc);

      if (!patientId) {
        return doc;
      }

      return fetchInvoiceSummary(patientId)
        .then(function () {
          return fetchTherapyPlans(patientId);
        })
        .then(function () {
          return fetchLastVisitGap(patientId);
        })
        .then(function () {
          return doc;
        });
    })
    .then(function () {
      switchMode(0, true);
      goToStep(Number(targetStep || 4));
    })
    .catch(function (e) {
      showValidationPopup("Unable To Open Request", [
        e.message || "Unable to load selected transfer request."
      ]);
    });
}

