  async function applyBranchTransferAfterFinalApproval() {
    if (!createdDocName) {
      throw new Error("Transfer Request is missing. Cannot apply branch transfer.");
    }

    const reqDoc = await frappeCall("frappe.client.get", {
      doctype: DOCTYPE,
      name: createdDocName
    });

    const patientName = getPatientIdFromRequestDoc(reqDoc);

    const transferToBranch = String(
      reqDoc.transfer_to_branch ||
      transferState.toBranch ||
      ""
    ).trim();

    if (!patientName) {
      throw new Error("Patient / Client is missing. Cannot update branch.");
    }

    if (!transferToBranch) {
      throw new Error("Transfer To Branch is missing. Cannot update Patient / Therapy Plan branch.");
    }

    try {
      await frappeCall("frappe.client.set_value", {
        doctype: "Patient",
        name: patientName,
        fieldname: {
          branch_name: transferToBranch,
          custom_branch: transferToBranch
        }
      });
    } catch (e1) {
      try {
        await frappeCall("frappe.client.set_value", {
          doctype: "Patient",
          name: patientName,
          fieldname: {
            branch_name: transferToBranch
          }
        });
      } catch (e2) {
        throw new Error(
          "Final approval saved, but Patient branch update failed: " +
          (e2.message || e1.message || "Unknown error")
        );
      }
    }
        try {
      const patientDoc = await frappeCall("frappe.client.get", {
        doctype: "Patient",
        name: patientName
      });

      let childField = "";

      if (Array.isArray(patientDoc.custom_brnch_list)) {
        childField = "custom_brnch_list";
      } else if (Array.isArray(patientDoc.custom_branch_list)) {
        childField = "custom_branch_list";
      }

      if (childField) {
        const rows = patientDoc[childField] || [];

        const alreadyExists = rows.some(function (r) {
          return String(r.branch || "").trim() === transferToBranch;
        });

        if (!alreadyExists) {
          rows.push({
            branch: transferToBranch,
            transfer_date: todayISO(),
            remarks: "Branch updated through Client Transfer Request " + createdDocName
          });

          const updateObj = {};
          updateObj[childField] = rows;

          await frappeCall("frappe.client.set_value", {
            doctype: "Patient",
            name: patientName,
            fieldname: updateObj
          });
        }
      }
    } catch (e3) {
      void 0;
    }

    const therapyPlans = await frappeCall("frappe.client.get_list", {
      doctype: "Therapy Plan",
      fields: ["name", "patient"],
      filters: [
        ["patient", "=", patientName]
      ],
      limit_page_length: 100
    });

    let updatedPlans = 0;

    for (const plan of therapyPlans || []) {
      if (!plan || !plan.name) continue;

      try {
        await frappeCall("frappe.client.set_value", {
          doctype: "Therapy Plan",
          name: plan.name,
          fieldname: {
            branch: transferToBranch,
            custom_transfer_branch: transferToBranch
          }
        });

        updatedPlans++;
      } catch (e) {
        void 0;
      }
    }

    await saveOptionalStageTimestamp(
      "custom_branch_transfer_completed_at"
    );

    if (selectedClient) {
      selectedClient.branch = transferToBranch;
    }

    return {
      patient: patientName,
      branch: transferToBranch,
      therapyPlansUpdated: updatedPlans
    };
  }

